package cn.sifangguan.hotelaios.finance;
import cn.sifangguan.hotelaios.shared.context.TenantPrincipal;
import cn.sifangguan.hotelaios.shared.security.AccessPolicy;
import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate;
import java.util.*;
import static cn.sifangguan.hotelaios.finance.FinanceV2Support.*;

/** A whole-company tax snapshot never becomes a single-hotel document merely by changing the reader's scope. */
public final class FinanceTaxScope {
 private FinanceTaxScope(){}
 public static List<UUID> companyHotels(NamedParameterJdbcTemplate jdbc,TenantPrincipal p,UUID company){String sources="select hotel_id from finance_store_config c join org_unit h on h.tenant_id=c.tenant_id and h.id=c.hotel_id where c.tenant_id=:tenant and c.company_id=:company and c.enabled and c.workflow_version=2 and h.status='ACTIVE' union select hotel_id from fa_book where tenant_id=:tenant and company_id=:company union select hotel_id from fb_input_tax where tenant_id=:tenant and company_id=:company union select q.hotel_id from fb_output_request q join fb_output_invoice i on i.tenant_id=q.tenant_id and i.request_id=q.id where q.tenant_id=:tenant and q.company_id=:company union select hotel_id from fb_revenue_entry where tenant_id=:tenant and company_id=:company";if(Boolean.TRUE.equals(jdbc.queryForObject("select to_regclass('ft_input_basis') is not null",Map.of(),Boolean.class)))sources+=" union select hotel_id from ft_input_basis where tenant_id=:tenant and company_id=:company";return jdbc.queryForList("select hotel_id from ("+sources+") actual order by hotel_id",base(p).addValue("company",company),UUID.class);}
 public static void company(NamedParameterJdbcTemplate jdbc,AccessPolicy access,TenantPrincipal p,UUID company){for(UUID hotel:companyHotels(jdbc,p,company))access.requireOrgScope(hotel);}
 /** Fixed internal alias only. Used in V110+ current-node SQL before pagination; the ft tables must be installed. */
 public static String readableSql(String alias){if(alias==null||!alias.matches("[A-Za-z][A-Za-z0-9_]*"))throw new IllegalArgumentException("Internal SQL alias required");String snapshot=alias+".snapshot",hotels=jsonArray(snapshot+"->'companyScopeHotelIds'"),frozen="not exists(select 1 from jsonb_array_elements_text("+hotels+") tax_scope_h(value) where "+safeUuid("tax_scope_h.value")+" is null or "+safeUuid("tax_scope_h.value")+" not in (:scopeIds))";String t=alias+".tenant_id",c=alias+".company_id",legacy="select hotel_id from finance_store_config sc join org_unit sh on sh.tenant_id=sc.tenant_id and sh.id=sc.hotel_id where sc.tenant_id="+t+" and sc.company_id="+c+" and sc.enabled and sc.workflow_version=2 and sh.status='ACTIVE' union select hotel_id from fa_book where tenant_id="+t+" and company_id="+c+" union select hotel_id from fb_input_tax where tenant_id="+t+" and company_id="+c+" union select oq.hotel_id from fb_output_request oq join fb_output_invoice oi on oi.tenant_id=oq.tenant_id and oi.request_id=oq.id where oq.tenant_id="+t+" and oq.company_id="+c+" union select hotel_id from fb_revenue_entry where tenant_id="+t+" and company_id="+c+" union select hotel_id from ft_input_basis where tenant_id="+t+" and company_id="+c;String company="not exists(select 1 from ("+legacy+") tax_scope_old where tax_scope_old.hotel_id not in (:scopeIds))",choice="case when "+snapshot+"->>'companyScopeVersion'='FROZEN_COMPANY_HOTELS_V1' and jsonb_array_length("+hotels+")>0 then "+frozen+" else "+company+" end";String facts="";for(String key:List.of("inputTaxSources","inputTaxBases")){String h=safeUuid("tax_scope_fact.value->>'hotelId'"),entity=safeUuid("tax_scope_fact.value->>'companyId'");facts+=" and not exists(select 1 from jsonb_array_elements("+jsonArray(snapshot+"->'"+key+"'")+") tax_scope_fact(value) where "+h+" is null or "+h+" not in (:scopeIds) or "+entity+" is distinct from "+c+")";}return "(:tenantScope or ("+alias+".hotel_id in (:scopeIds) and ("+choice+")"+facts+"))";}
 private static String jsonArray(String expression){return "case when jsonb_typeof("+expression+")='array' then "+expression+" else '[]'::jsonb end";}
 private static String safeUuid(String expression){return "(case when ("+expression+") ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' then cast(("+expression+") as uuid) else null end)";}
 public static void frozen(NamedParameterJdbcTemplate jdbc,AccessPolicy access,TenantPrincipal p,Map<String,Object> taxReturn){UUID hotel=id(taxReturn.getOrDefault("hotel_id",taxReturn.get("hotelId"))),company=id(taxReturn.getOrDefault("company_id",taxReturn.get("companyId")));if(hotel==null||company==null)throw conflict("税务冻结来源缺少真实组织或法人，禁止猜测授权范围");access.requireOrgScope(hotel);var snapshot=map(taxReturn.get("snapshot"));if("FROZEN_COMPANY_HOTELS_V1".equals(snapshot.get("companyScopeVersion"))&&snapshot.get("companyScopeHotelIds") instanceof List<?> hotels&&!hotels.isEmpty()){for(Object actual:hotels)access.requireOrgScope(id(actual));}else company(jdbc,access,p,company);for(String key:List.of("inputTaxSources","inputTaxBases"))if(snapshot.get(key) instanceof List<?> facts)for(Object item:facts){var fact=map(item);UUID actualHotel=id(fact.get("hotelId")),actualCompany=id(fact.get("companyId"));if(actualHotel==null||!company.equals(actualCompany))throw conflict("冻结逐票链与真实申报主体不同，不能按当前数据重配历史范围");access.requireOrgScope(actualHotel);}}
 public static void forReturn(NamedParameterJdbcTemplate jdbc,AccessPolicy access,TenantPrincipal p,UUID id){var rows=jdbc.queryForList("select * from fb_tax_return where tenant_id=:tenant and id=:id",base(p).addValue("id",id));if(rows.size()!=1)throw missing();frozen(jdbc,access,p,rows.getFirst());}
}
